// Talks to the coa MCP server with plain JSON-RPC over HTTP. The desk does not
// declare the server itself: that would give Claude a second copy of every
// tool. The server is stateless, so tools/call needs no session.

export const MCP_URL = 'https://coa.davebream.com/mcp'
export const MCP_HEADERS = {
  'content-type': 'application/json',
  accept: 'application/json, text/event-stream',
}

export type RpcResponse =
  | { isError: false; payload: any }
  | { isError: true; message: string }

export function rpcBody(tool: string, args: Record<string, unknown>, id = 1): string {
  return JSON.stringify({ jsonrpc: '2.0', id, method: 'tools/call', params: { name: tool, arguments: args } })
}

function lastMessage(text: string): any {
  const data = text
    .split('\n')
    .filter((line) => line.startsWith('data: '))
    .map((line) => line.slice(6))
  return JSON.parse(data.length > 0 ? data[data.length - 1] : text)
}

function errorText(content: unknown): string {
  const text = Array.isArray(content) ? content.find((block) => block?.type === 'text')?.text : undefined
  if (typeof text !== 'string') return 'The server returned an error'
  try {
    return JSON.parse(text)?.error?.message ?? text
  } catch {
    return text
  }
}

export function parseRpcResponse(text: string): RpcResponse {
  let message: any
  try {
    message = lastMessage(text)
  } catch {
    return { isError: true, message: 'The server sent a response that is not JSON' }
  }
  if (message?.error) return { isError: true, message: String(message.error.message ?? 'Request failed') }
  const result = message?.result
  if (!result) return { isError: true, message: 'The server sent no result' }
  if (result.isError) return { isError: true, message: errorText(result.content) }
  if (result.structuredContent) return { isError: false, payload: result.structuredContent }
  try {
    return { isError: false, payload: JSON.parse(result.content?.[0]?.text ?? '') }
  } catch {
    return { isError: true, message: 'The server sent a result without data' }
  }
}

files.hooks/passage.ts:
// Renders a parallel_text payload as Markdown for the passage pane.

type Verse = { chapter: number; verse: number; translations: Record<string, string> }
type Dataset = { id: string; title?: string }

export function renderPassage(payload: any): string {
  const verses: Verse[] = Array.isArray(payload?.verses) ? payload.verses : []
  const lines = [`## ${payload?.book ?? ''} ${payload?.range ?? ''}`.trim(), '']
  for (const verse of verses) {
    lines.push(`**${verse.chapter}:${verse.verse}**`)
    for (const [translation, text] of Object.entries(verse.translations ?? {})) {
      lines.push(`- ${translation}: ${text}`)
    }
    lines.push('')
  }
  if (Array.isArray(payload?.missing_verses) && payload.missing_verses.length > 0) {
    lines.push(`Missing in some translations: ${payload.missing_verses.join(', ')}`, '')
  }
  if (payload?.versification_note) lines.push(`_${payload.versification_note}_`, '')
  const datasets: Dataset[] = Array.isArray(payload?.provenance?.datasets) ? payload.provenance.datasets : []
  if (datasets.length > 0) {
    lines.push(`Sources: ${datasets.map((dataset) => dataset.title ?? dataset.id).join('; ')}`)
  }
  return lines.join('\n').trimEnd()
}

files.hooks/provenance.ts:
// Pulls dataset ids out of a coa tool result. Every successful coa response
// carries provenance.datasets[].id; a tool.call result can hold it as an
// object, a JSON string, an MCP content block, or wrapped in { result, text }.

function fromValue(value: unknown, depth: number): string[] {
  if (depth > 4 || value === null || value === undefined) return []
  if (typeof value === 'string') {
    try {
      return fromValue(JSON.parse(value), depth + 1)
    } catch {
      return []
    }
  }
  if (typeof value !== 'object') return []
  const record = value as Record<string, any>
  const datasets = record.provenance?.datasets
  if (Array.isArray(datasets)) {
    return datasets.map((dataset) => dataset?.id).filter((id): id is string => typeof id === 'string')
  }
  for (const key of ['structuredContent', 'text', 'result']) {
    const ids = fromValue(record[key], depth + 1)
    if (ids.length > 0) return ids
  }
  if (Array.isArray(record.content)) {
    for (const block of record.content) {
      const ids = fromValue(block?.text, depth + 1)
      if (ids.length > 0) return ids
    }
  }
  return []
}

export function datasetIdsOf(value: unknown): string[] {
  return [...new Set(fromValue(value, 0))]
}

